const response = $input.first().json;
const places = response.places || response.results || [];

let query = 'roofers';
let location = 'london';
let minReviews = 1;
try {
  const fields = $('Edit Fields').first().json;
  if (fields.query) query = fields.query;
  if (fields.location) location = fields.location;
  if (fields.min_reviews !== undefined) minReviews = Number(fields.min_reviews);
} catch (e) {}

function getTrade(name, category, q) {
  const text = `${name} ${category} ${q}`.toLowerCase();
  if (text.includes('roof')) return 'Roofer';
  if (text.includes('plumb') || text.includes('drain') || text.includes('heat')) return 'Plumber';
  if (text.includes('electr')) return 'Electrician';
  if (text.includes('dent') || text.includes('smile')) return 'Dentist';
  if (text.includes('account') || text.includes('tax')) return 'Accountant';
  if (text.includes('build') || text.includes('construct') || text.includes('loft')) return 'Builder';
  if (text.includes('clean')) return 'Cleaner';
  if (text.includes('landscap') || text.includes('tree') || text.includes('garden')) return 'Landscaper';
  return 'Local Business';
}

const output = [];
const seenPhones = new Set();

for (const place of places) {
  const name = (place.title || place.name || '').trim();
  const rawPhone = (place.phoneNumber || place.phone || '').trim();
  const rawWebsite = (place.website || '').trim();
  const rating = Number(place.rating || 0);
  const reviewsCount = Number(place.ratingCount || place.user_ratings_total || 0);
  const address = (place.address || place.formatted_address || location).trim();
  const category = place.category || place.type || '';

  if (!name || !rawPhone) continue;
  if (reviewsCount < minReviews) continue;

  // Normalize phone
  let cleanPhone = rawPhone.replace(/[^0-9+]/g, '');
  if (cleanPhone.startsWith('0')) {
    cleanPhone = '+44' + cleanPhone.substring(1);
  }
  if (!cleanPhone.startsWith('+44')) {
    cleanPhone = '+44' + cleanPhone.replace(/^\+/, '');
  }

  // Deduplication
  if (seenPhones.has(cleanPhone)) continue;
  seenPhones.add(cleanPhone);

  const isMobile = cleanPhone.startsWith('+447');
  const channel = isMobile ? 'WhatsApp / SMS' : 'Landline / Direct Call';
  const waDigits = cleanPhone.replace('+', '');
  const waLink = isMobile ? `https://wa.me/${waDigits}?text=${encodeURIComponent('Hi 👋')}` : 'N/A';

  // Check website status
  let hasWebsite = true;
  let classification = 'has_website';
  if (!rawWebsite || rawWebsite === '' || rawWebsite.toLowerCase() === 'none') {
    hasWebsite = false;
    classification = 'no_website';
  } else {
    const w = rawWebsite.toLowerCase();
    if (w.includes('facebook.com') || w.includes('instagram.com') || w.includes('yell.com') || w.includes('checkatrade.com')) {
      hasWebsite = false;
      classification = 'social_only';
    }
  }

  const trade = getTrade(name, category, query);

  // Cold outreach message generation
  const stage1Opener = 'Hi 👋';
  const stage2Pitch = !hasWebsite
    ? `Came across ${name} — had a look for your website, couldn't find one. Every day someone searches for a ${trade.toLowerCase()} near them in ${location}, sees you're not there, and books with whoever showed up instead. I build the site and automated quote booking system before asking for a penny. If it's not for you, no pressure at all.`
    : `Came across ${name} — saw your site, but noticed it isn't optimized for instant mobile booking and automated lead capture. We turn your visitors into booked jobs automatically.`;

  output.push({
    json: {
      "Business Name": name,
      "Phone": cleanPhone,
      "Has Website": hasWebsite,
      "Classification": classification,
      "Website": rawWebsite || 'None',
      "Google Rating": rating,
      "Reviews Count": reviewsCount,
      "Address": address,
      "Category": trade,
      "Channel": channel,
      "WhatsApp Link": waLink,
      "Stage 1 Opener": stage1Opener,
      "Stage 2 Pitch": stage2Pitch,
      "Search Query": `${query} in ${location}`,
      "Lead Priority": !hasWebsite ? 'High (No Website)' : 'Standard (Has Website)'
    }
  });
}

return output;
